      expect(message).toContain("Session password list is empty");
    }

    const blank = await (await t.fetch("/invalid/blank")).json();
    for (const message of blank.messages) {
      expect(message).toContain("Session passwords must be non-empty strings");
    }

    const nonString = await (await t.fetch("/invalid/nonString")).json();
    for (const message of nonString.messages) {
      expect(message).toContain("Session passwords must be non-empty strings");
    }
  });
