  const { password } = config;
  if (!Array.isArray(password)) {
    return [password];
  }
  if (password.length === 0) {
    throw new Error("Session password list is empty");
  }
  for (const item of password) {
    if (typeof item !== "string" || !item) {
      throw new Error("Session passwords must be non-empty strings");
    }
  }
  return password;
}

/**
