  beforeEach(() => {
    t.app.get("/get", async (event) => {
      const session = await getSession(event, rotating);
      return { id: session.id, data: session.data };
    });
    t.app.post("/update", async (event) => {
      const session = await useSession(event, rotating);
      await session.update({ foo: "bar" });
      return { id: session.id, data: session.data };
    });
  });

  // RF-01
  it("seals new sessions with the first password of the list", async () => {
    const res = await t.fetch("/update", { method: "POST" });
    const sealed = sealedFrom(res);

    expect(await unseal(sealed, NOVA, sealDefaults)).toMatchObject({ data: { foo: "bar" } });
    await expect(unseal(sealed, ANTIGA, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  // RF-02
  it("reads a session sealed with an older password of the list", async () => {
    const sealed = await seal(
      { id: "orig-id", createdAt: Date.now(), data: { foo: "antiga" } },
      ANTIGA,
      sealDefaults,
    );

    const res = await t.fetch("/get", { headers: { Cookie: `h3-test=${sealed}` } });
    expect(await res.json()).toEqual({ id: "orig-id", data: { foo: "antiga" } });
  });

  // RF-03
  it("treats a session sealed with an unknown password as a new session", async () => {
    const sealed = await seal(
      { id: "orig-id", createdAt: Date.now(), data: { foo: "secreto" } },
      DESCONHECIDA,
      sealDefaults,
    );

    const res = await t.fetch("/get", { headers: { Cookie: `h3-test=${sealed}` } });
    const body = await res.json();
    expect(body.id).not.toBe("orig-id");
    expect(body.data).toEqual({});
  });

  // RF-04
  it("reseals a session read with an older password using the first password", async () => {
    const sealed = await seal(
      { id: "orig-id", createdAt: Date.now(), data: { foo: "antiga" } },
      ANTIGA,
      sealDefaults,
    );

    const res = await t.fetch("/update", {
      method: "POST",
      headers: { Cookie: `h3-test=${sealed}` },
    });
    const resealed = sealedFrom(res);

    expect(await unseal(resealed, NOVA, sealDefaults)).toMatchObject({
      id: "orig-id",
      data: { foo: "bar" },
    });
    await expect(unseal(resealed, ANTIGA, sealDefaults)).rejects.toThrow("Bad hmac value");
    // Internal markers must not leak into the sealed payload
    const payload = (await unseal(resealed, NOVA, sealDefaults)) as Record<string, unknown>;
    expect(Object.keys(payload).sort()).toEqual(["createdAt", "data", "id"]);
  });

  // RF-04 (idleTimeout slide)
  it("reseals an idle-sliding session opened with an older password using the first password", async () => {
    const idleConfig = config([NOVA, ANTIGA], { idleTimeout: 3600 });
    t.app.get("/idle", async (event) => {
      const session = await getSession(event, idleConfig);
      return { id: session.id };
    });
    const sealed = await seal(
      {
        id: "orig-id",
        createdAt: Date.now() - 2100 * 1000,
        data: { foo: "antiga" },
      },
      ANTIGA,
      sealDefaults,
    );

    const res = await t.fetch("/idle", { headers: { Cookie: `h3-test=${sealed}` } });
    expect(await res.json()).toEqual({ id: "orig-id" });
    const resealed = sealedFrom(res);
    expect(await unseal(resealed, NOVA, sealDefaults)).toMatchObject({ id: "orig-id" });
    await expect(unseal(resealed, ANTIGA, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  // RF-06
  it("opens a legacy 1-iteration session sealed with a non-first password and reseals it", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      ANTIGA,
      LEGACY_SEAL_OPTIONS,
    );

    const res = await t.fetch("/get", { headers: { Cookie: `h3-test=${legacySealed}` } });
    expect(await res.json()).toEqual({ id: "legacy", data: { foo: "legacy" } });

    const resealed = sealedFrom(res);
    expect(await unseal(resealed, NOVA, sealDefaults)).toMatchObject({
      id: "legacy",
      data: { foo: "legacy" },
    });
  });

  // RF-08
  it("expires an older-password session by maxAge the same way as a current one", async () => {
    const maxAgeConfig = config([NOVA, ANTIGA], { maxAge: 60 });
    t.app.get("/max", async (event) => {
      const session = await getSession(event, maxAgeConfig);
      return { id: session.id };
    });
    const sealed = await seal(
      { id: "old", createdAt: Date.now() - 120 * 1000, data: { foo: "antiga" } },
      ANTIGA,
      sealDefaults,
    );

    const res = await t.fetch("/max", { headers: { Cookie: `h3-test=${sealed}` } });
    const body = await res.json();
    expect(body.id).not.toBe("old");
  });

  // RF-09
  it("reads an older-password session sent in the session header", async () => {
    const sealed = await seal(
      { id: "orig-id", createdAt: Date.now(), data: { foo: "antiga" } },
      ANTIGA,
      sealDefaults,
    );

    const res = await t.fetch("/get", { headers: { "x-h3-test-session": sealed } });
    expect(await res.json()).toEqual({ id: "orig-id", data: { foo: "antiga" } });
    // Header sessions are not resealed
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  // RF-05
  it("keeps single-password behavior: string password reads and reseals with the same password", async () => {
    const single = config(NOVA);
    t.app.get("/single", async (event) => {
      const session = await getSession(event, single);
      return { id: session.id, data: session.data };
    });
    const sealed = await seal(
      { id: "current", createdAt: Date.now(), data: { foo: "atual" } },
      NOVA,
      sealDefaults,
    );

    const res = await t.fetch("/single", { headers: { Cookie: `h3-test=${sealed}` } });
    expect(await res.json()).toEqual({ id: "current", data: { foo: "atual" } });
    // Current seal is not resealed for a string password
    expect(res.headers.getSetCookie()).toHaveLength(0);

    const unsealed = await unsealSession({} as any, single, sealed);
    expect(unsealed).toMatchObject({ id: "current" });
  });

  // RF-07
  it("rejects an empty or invalid password list with a clear error", async () => {
    const invalid = {
      empty: [] as string[],
      blank: [""],
      nonString: [1 as any],
    };
    t.app.get("/invalid/:kind", async (event) => {
      const cfg = config(invalid[event.context.params!.kind as keyof typeof invalid]);
      const calls = [
        () => getSession(event, cfg),
        () => updateSession(event, cfg),
        () => sealSession(event, cfg),
        () => unsealSession(event, cfg, "x"),
        () => useSession(event, cfg),
      ];
      const messages: string[] = [];
      for (const call of calls) {
        try {
          await call();
          messages.push("ok");
        } catch (error) {
          messages.push((error as Error).message);
        }
      }
      return { messages };
    });

    const empty = await (await t.fetch("/invalid/empty")).json();
    for (const message of empty.messages) {
      expect(message).toContain("Session password list is empty");
    }

    const blank = await (await t.fetch("/invalid/blank")).json();
    for (const message of blank.messages) {
      expect(message).toContain("Session passwords must be non-empty strings");
    }

    const nonString = await (await t.fetch("/invalid/nonString")).json();
    for (const message of nonString.messages) {
      expect(message).toContain("Session passwords must be non-empty strings");
    }
  });
});
